public static int findDifferingCharacterIndex(String s) {
    String[] S = s.split("");
    String ini = S[0];
    int countIni = 0;
    int countOther = 0;
    String other = "";

    // Determine the majority character
    for (int i = 0; i < 3; i++) {
        if (S[i].equals(ini)) {
            countIni++;
        } else {
            other = S[i];
            countOther++;
        }
    }

    String majority = countIni > countOther ? ini : other;

    // Find the differing character
    for (int i = 0; i < S.length; i++) {
        if (!S[i].equals(majority)) {
            return i + 1;
        }
    }

    return -1; // This line should never be reached if input is valid
}
